from __future__ import annotations

TREND_TOLERANCE = 5

REQUIRED_FIELDS = ("values", "timestamps", "expected_step", "hard_limit")

# Spike-severity bands: (threshold, label, score), in descending priority.
# The per-call hard_limit forms the highest "invalid" band at the top.
_SPIKE_BANDS = (
    (12, "severe", 25),
    (6, "moderate", 10),
    (3, "minor", 3),
)
_WORST_BY_SCORE = {100: "invalid", 25: "severe", 10: "moderate", 3: "minor"}


def qc_series(raw: object) -> dict:
    error = _validate_input(raw)
    if error is not None:
        return {"ok": False, "error": error}
    values = raw["values"]
    timestamps = raw["timestamps"]
    gaps = _count_gaps(timestamps, raw["expected_step"])
    labels, total, worst = classify_spikes(_deviations(values), raw["hard_limit"])
    return {
        "ok": True,
        "labels": labels,
        "gaps": gaps,
        "score": total,
        "verdict": _verdict(total),
        "counts": _label_counts(labels),
        "trend": _trend(values),
        "streak": _longest_run(labels),
        "line": _summary_line(len(values), gaps, worst, total),
    }


def _validate_input(raw: object) -> str | None:
    if not isinstance(raw, dict):
        return "malformed input"
    if any(key not in raw for key in REQUIRED_FIELDS):
        return "missing field"
    values = raw["values"]
    timestamps = raw["timestamps"]
    if not isinstance(values, list) or not values:
        return "bad values"
    if not isinstance(timestamps, list) or len(timestamps) != len(values):
        return "bad timestamps"
    for value, stamp in zip(values, timestamps):
        if not isinstance(value, int) or not isinstance(stamp, int):
            return "bad sample"
    for index in range(1, len(timestamps)):
        if timestamps[index] <= timestamps[index - 1]:
            return "unordered timestamps"
    if not isinstance(raw["expected_step"], int) or raw["expected_step"] <= 0:
        return "bad step"
    if not isinstance(raw["hard_limit"], int) or raw["hard_limit"] <= 0:
        return "bad limit"
    return None


def _count_gaps(timestamps: list, expected_step: int) -> int:
    gaps = 0
    for index in range(1, len(timestamps)):
        if timestamps[index] - timestamps[index - 1] > expected_step:
            gaps = gaps + 1
    return gaps


def _deviations(values: list) -> list:
    deviations = []
    for index in range(len(values)):
        previous = values[index - 1] if index > 0 else values[index]
        following = values[index + 1] if index + 1 < len(values) else values[index]
        deviations.append(abs(values[index] - _median3(previous, values[index], following)))
    return deviations


def _median3(a: int, b: int, c: int) -> int:
    if a > b:
        a, b = b, a
    if b > c:
        b, c = c, b
    if a > b:
        a, b = b, a
    return b


def _spike_band(deviation: int, hard_limit: int) -> tuple:
    if deviation >= hard_limit:
        return "invalid", 100
    for threshold, label, score in _SPIKE_BANDS:
        if deviation >= threshold:
            return label, score
    return "clean", 0


def classify_spikes(deviations: list, hard_limit: int) -> tuple:
    labels = []
    total = 0
    worst = 0
    for deviation in deviations:
        label, score = _spike_band(deviation, hard_limit)
        labels.append(label)
        total = total + score
        if score > worst:
            worst = score
    return labels, total, worst


def _worst_label(worst_score: int) -> str:
    return _WORST_BY_SCORE.get(worst_score, "clean")


def _label_counts(labels: list) -> dict:
    counts = {"clean": 0, "minor": 0, "moderate": 0, "severe": 0, "invalid": 0}
    for label in labels:
        counts[label] = counts[label] + 1
    return counts


def _trend(values: list) -> str:
    delta = values[-1] - values[0]
    if delta > TREND_TOLERANCE:
        return "rising"
    if delta < -TREND_TOLERANCE:
        return "falling"
    return "stable"


def _longest_run(labels: list) -> int:
    longest = 0
    current = 0
    for label in labels:
        if label == "clean":
            current = 0
        else:
            current = current + 1
            if current > longest:
                longest = current
    return longest


def _verdict(total: int) -> str:
    if total >= 100:
        return "fail"
    if total >= 25:
        return "warn"
    return "pass"


def _summary_line(count: int, gaps: int, worst_score: int, total: int) -> str:
    return "n=" + str(count) + ";gaps=" + str(gaps) + ";worst=" + _worst_label(worst_score) + ";score=" + str(total)

